/**
 * Narration-driven timing (pure, runs in Node and in the Remotion bundle).
 *
 * A video's *timing lock* (content/timing/<id>.ts, generated by `npm run voice`) records how
 * long each spoken line of its take is, where it sat in the one-utterance recording, and
 * every word's start and end. With it, a content file can leave out absolute times:
 *   - narration lines without `at` follow the take's own rhythm (+ optional `pause`);
 *   - scenes without `duration` span from their first spoken line to the next scene's;
 *   - any beat can be a TimeRef: "when she says *anyway*", resolved to seconds here.
 * Change the script → re-run `npm run voice` → every time follows. Without a lock,
 * durations are estimated (for storyboarding) and the spec is flagged not buildable.
 */

/** A moment written against the narration. Resolves to scene-local seconds. */
export type TimeRef = {
  line: string;
  /** A spoken word in that line (case and punctuation ignored). Omit for the line itself. */
  word?: string;
  /** Which occurrence of the word (1-based). Default 1. */
  nth?: number;
  /** Start (default) or end of the word/line. */
  edge?: 'start' | 'end';
  /** Seconds added after resolving (may be negative). */
  offset?: number;
};

export function isTimeRef(x: unknown): x is TimeRef {
  return typeof x === 'object' && x !== null && 'line' in x && typeof (x as TimeRef).line === 'string';
}

/** A number field that may be written as a TimeRef while authoring. */
export type Timed<T> = T extends number
  ? number | TimeRef
  : T extends ReadonlyArray<infer U>
    ? Array<Timed<U>>
    : T extends object
      ? { [K in keyof T]: Timed<T[K]> }
      : T;

export type LockWord = [text: string, start: number, end: number];
export type LockLine = { id: string; text: string; duration: number; sourceStart: number; words: LockWord[] };
export type TimingLock = {
  video: string;
  /** Where the audio is: an approved take (public/narration/…) or the draft cache (.cache/narration/…). */
  source: { kind: 'approved' | 'draft'; path: string };
  voice: string;
  /** fnv1a of the script (ids + texts) the lock was made from. */
  scriptHash: string;
  lines: LockLine[];
};

/** FNV-1a 32-bit, hex. Deterministic in Node and the browser (staleness check only). */
export function fnv1a(s: string): string {
  let h = 0x811c9dc5;
  for (let i = 0; i < s.length; i++) {
    h ^= s.charCodeAt(i);
    h = Math.imul(h, 0x01000193) >>> 0;
  }
  return h.toString(16).padStart(8, '0');
}

export function scriptHash(lines: ReadonlyArray<{ id: string; text: string }>): string {
  return fnv1a(JSON.stringify(lines.map((l) => [l.id, l.text])));
}

const norm = (w: string) => w.toLowerCase().replace(/[^\p{L}\p{N}']/gu, '').replace(/’/g, "'");

/** Estimated timing for a script without a take (storyboarding): ~2.7 words/s. */
export function estimateLock(video: string, lines: ReadonlyArray<{ id: string; text: string }>): TimingLock {
  let src = 0.2;
  const out: LockLine[] = lines.map((l) => {
    const ws = l.text.split(/\s+/).filter(Boolean);
    let t = 0.05;
    const words: LockWord[] = ws.map((w) => {
      const d = 0.16 + w.replace(/[^\p{L}]/gu, '').length * 0.045;
      const word: LockWord = [w, t, t + d];
      t += d + (/[.,!?]$/.test(w) ? 0.18 : 0.02);
      return word;
    });
    const line: LockLine = { id: l.id, text: l.text, duration: t + 0.1, sourceStart: src, words };
    src += line.duration + 0.3;
    return line;
  });
  return { video, source: { kind: 'draft', path: '(estimated)' }, voice: '(estimated)', scriptHash: scriptHash(lines), lines: out };
}

/** Seconds from the start of `line` to the referenced word edge (or the line edge). */
export function wordOffset(line: LockLine, ref: Pick<TimeRef, 'word' | 'nth' | 'edge'>): number {
  if (!ref.word) return ref.edge === 'end' ? line.duration : 0;
  const target = norm(ref.word);
  let seen = 0;
  for (const [text, start, end] of line.words) {
    if (norm(text) === target && ++seen === (ref.nth ?? 1)) return ref.edge === 'end' ? end : start;
  }
  throw new Error(`timing: "${ref.word}" is not spoken in line "${line.id}"`);
}
